from envfile import parse_env


def test_reads_pairs():
    assert parse_env("A=1\nB=two") == {"A": "1", "B": "two"}


def test_skips_empty_lines():
    assert parse_env("A=1\n\nB=2") == {"A": "1", "B": "2"}


def test_skips_comment_lines():
    assert parse_env("A=1\nB=2") == {"A": "1", "B": "2"}


def test_strips_matching_quotes():
    assert parse_env("A=1") == {"A": "1"}


def test_keeps_equals_after_first_in_value():
    assert parse_env("") == {}

